with with_windows as (select id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, ntile(3) over (order by salary, id) salary_bucket, round(salary / sum(salary) over (partition by dept_id), 4) salary_share, max(salary) over (partition by job_title) job_title_max_salary from employees) select id, full_name, email, dept_id, job_title, salary, hire_date, salary_bucket, job_title_max_salary, case when full_name rlike '^(Pim Chaiyaporn|Ivy Chen)$' then 'EXTENDED' when full_name rlike '^(Alice Wong|bob smith)$' then 'CORE' else 'GROUP_A' end as full_name_zone from with_windows order by job_title_max_salary desc nulls first, job_title;
